In some browsers, the stalled event is not fired when the video is paused due to lack of data. Instead, you can check the buffered property of the video element. If the current time is greater than the end of the buffered range, then the video is stalled. Here is a simple example:

var vid = $('video')[0];
vid.addEventListener('timeupdate', function() {
    if (vid.currentTime > vid.buffered.end(0)) {
        console.log('Media stalled...');
        // Add visual indication here
    } else {
        console.log('Media playing...');
        // Remove visual indication here
    }
});

